from taf.sbts.oam.coam.admin import admin
import time


class CellOperations(object):

    def check_cells_are_in_given_status(self, cell_ids, cells_status, timeout='480'):  # noqa: C901
        logger.info('\ncells_status: {}; cell_ids: {}; '.format(cell_ids, cells_status), also_console=True)
        try:
            admin_client = admin()
            admin_client.connect_to()
            time_step = 10
            timeout = int(timeout)
            time_start = time.time()
            nrcel_dist_name = ""
            if isinstance(cells_status, str):
                cells_status = [cells_status]
            while time.time() < time_start + timeout:
                given_status = True
                status_list = []
                for cell_id, cell_status in zip(cell_ids, cells_status):
                    try:
                        nrcel_dist_name = admin_client.get_cell_id_by_configuration_id(rat="NR",
                                                                                       configuration_id=str(
                                                                                           cell_id))
                    except Exception:
                        logger.warn('get_cell_id_by_configuration_id failed')
                    result = admin_client.get_cell_specific_info(cell_id=nrcel_dist_name)
                    logger.info('Cell: {}; AdministrativeState cell status -expected: {}; -current: {}'.
                                format(cell_id, cell_status, result['status']['administrativeState']),
                                also_console=True)
                    if cell_status not in result['status']['administrativeState']:
                        given_status = False
                    status_list.append(given_status)
                if all(status_list):
                    duration = time.time() - time_start
                    logger.info('Waiting time to reach expected cell(s) status: {} s'.format(duration),
                                also_console=True)
                    return duration
                time.sleep(time_step)
        finally:
            admin_client.teardown()
        raise ExecutionFailed(message="Cell(s) is/are not in expected status!")

    def check_single_cell_classical(self, cell_id, search_key, expected_state):
        """
        Checks value of defined parameter in a single cell
        :param cell_id:
        :param search_key:
        :param expected_state:
        :return:
        """

        with ta_admin_interface.admin_interface() as admin_client:
            cells_info = admin_client.get_cells_info()
        cell_info = [cell['status'][search_key] for cell in cells_info if cell['globalCellId'] == int(cell_id)]
        ta5g_admin_operations().assert_equal(expected=expected_state.lower(), actual=cell_info[0].lower())

    def check_single_cell_aic(self, cell_id, search_key, expected_state):
        """
        Checks value of defined parameter in a single cell in vcu aic
        :param cell_id:
        :param search_key: e.g. administrative_state
        :param expected_state:
        :return:
        """

        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            cells_statuses = vcu_connection.get_cells_statuses()
        cell_info = [cell[search_key].lower() for cell in cells_statuses if cell['id'] == str(cell_id)]
        ta5g_admin_operations().assert_equal(expected=expected_state.lower(), actual=cell_info[0].lower())

    def check_single_cell_vdu_aic(self, cell_id, search_key, expected_state, vdu=1):
        """
        Checks value of defined parameter(search_key) in a single cell in vdu aic
        :param cell_id:
        :param search_key: e.g. procedural_status, availability_status of cell
        :param expected_state:
        :param vdu: by default set to 1
        :return:
        """
        vdu = int(vdu)
        tl = BuiltIn().get_variable_value("${tl}")
        vdu_oam_ip = tl.gnbs[0].dus[vdu - 1].oam_http_connection_details.addr
        with ta5g_admin_operations().connect_to_vdu_aic(vdu_oam_ip) as vdu_connection:
            cells_statuses = vdu_connection.get_vdu_cells_status()
        cell_info = [cell[search_key].lower() for cell in cells_statuses if cell['id'] == str(cell_id)]
        ta5g_admin_operations().assert_equal(expected=expected_state.lower(), actual=cell_info[0].lower())

    def check_single_cell(self, cell_id, search_key, expected_state):
        if ta5g_admin_operations().is_classical():
            self.check_single_cell_classical(cell_id, search_key, expected_state)
        else:
            self.check_single_cell_aic(cell_id, search_key, expected_state)

    def check_cells_are_in_correct_state_classical(self, cell_ids, search_key, cells_status):
        if isinstance(cells_status, str):
            cells_status = [cells_status]
        for cell_id, cell_status in zip(cell_ids, cells_status):
            self.check_single_cell(cell_id, search_key, cell_status)

    def check_cells_are_in_correct_state_aic(self, cell_ids, search_key, cells_status):
        """
        Checks value of defined parameter in a list of cells in vcu aic
        :param cell_ids:
        :param search_key: e.g. administrative_state
        :param cells_status: list of expected cells statuses
        :return:
        """
        if isinstance(cells_status, str):
            cells_status = [cells_status]
        for cell_id, cell_status in zip(cell_ids, cells_status):
            self.check_single_cell_aic(cell_id, search_key, cell_status)

