    def check_all_cells_classical(self, search_key, expected_state, remote_host=None):
        """
        Checks value of defined parameter in all available cells
        :param search_key:
        :param expected_state:
        :return:
        """
        logger.console('Check All Cells Classical remote_host={}'.format(remote_host))

        with ta_admin_interface.get_admin_interface(remote_host=remote_host) as admin_client:
            cells_info = admin_client.get_cells_info()
        for cell in cells_info:
            actual = cell['status'][search_key].lower()
            logger.console('\t Cell {} status: {}'.format(cell['globalCellId'], actual))
            ta5g_admin_operations().assert_equal(
                expected=expected_state.lower(), actual=actual,
                message="Cell with id {} is {}\nCell should be {}".format(cell['globalCellId'], actual, expected_state)
            )

    def check_all_cells_aic(self, search_key, expected_state):
        """
        Checks value of defined parameter in all available cells aic in vcu aic
        :param search_key:
        :param expected_state:
        :return:
        """
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            cells_statuses = vcu_connection.get_cells_statuses()
            for cell in cells_statuses:
                actual = cell[search_key].lower()
                ta5g_admin_operations().assert_equal(
                    expected=expected_state.lower(), actual=actual,
                    message="Cell with id {} is {}\nCell should be {}".format(cell['id'], actual, expected_state)
                )

    def check_selected_cells(self, cell_list, search_key, expected_state):
        """
        Checks value of defined parameter in selected available cells
        :param cell_list:
        :param search_key:
        :param expected_state:
        :return:
        """
        with ta_admin_interface.admin_interface() as admin_client:
            cells_info = admin_client.get_cells_info()

        for cell in cells_info:
            if cell["globalCellId"] in cell_list:
                actual = cell['status'][search_key].lower()
                ta5g_admin_operations().assert_equal(
                    expected=expected_state.lower(), actual=actual,
                    message="Cell with id {} is {}\nCell should be {}".format(cell['globalCellId'],
                                                                              actual,
                                                                              expected_state)
                )

    def check_all_cells(self, search_key, expected_state, remote_host=None):
        if ta5g_admin_operations().is_classical():
            self.check_all_cells_classical(search_key, expected_state, remote_host=remote_host)
        else:
            self.check_all_cells_aic(search_key, expected_state)

