    def check_cell_parameter_value_classical(self, global_cell_id, parameter, remote_host=None):
        value = None
        with ta_admin_interface.get_admin_interface(remote_host=remote_host) as admin_client:
            for cell in admin_client.get_cells_info():
                if str(cell['globalCellId']) == str(global_cell_id):
                    value = cell[parameter]
        if value is None:
            raise Exception('Parameter {} not found for cell id {}'.format(parameter, global_cell_id))
        return value

    def check_cell_parameter_value_aic(self, global_cell_id, parameter):
        """
        Check cell parameter and return value of parameter for given cell in vcu aic
        :param global_cell_id:
        :param parameter: e.g. cellDepType
        :return:
        """
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            cells_statuses = vcu_connection.get_parameters(dist_name='MRBTS-1/NRBTS-1/NRCELL-{}'.format(global_cell_id))
            for idx in range(len(cells_statuses['parameters'])):
                try:
                    if (cells_statuses['parameters'][idx]['simple_parameter']).name == parameter:
                        return (cells_statuses['parameters'][idx]['simple_parameter']).value
                except Exception:
                    continue

    def check_cell_parameter_value(self, global_cell_id, parameter, remote_host=None):
        if ta5g_admin_operations().is_classical():
            return self.check_cell_parameter_value_classical(global_cell_id, parameter, remote_host=remote_host)
        else:
            return self.check_cell_parameter_value_aic(global_cell_id, parameter)

    def check_if_sansa_cell(self, global_cell_id, remote_host=None):
        if self.check_cell_parameter_value(global_cell_id=global_cell_id, parameter='cellDepType', remote_host=remote_host) in \
                ('both', 'SA+NSA'):
            return True
        else:
            return False

