    def check_if_there_is_no_active_alarm_on_any_cell(self):
        with ta_admin_interface.admin_interface() as admin_client:
            for alarm in admin_client.get_active_alarms():
                if len(alarm['impactedCellsList']) != 0:
                    raise ExecutionFailed(message="Active alarms detected!", continue_on_failure=True)
            logger.info("No active alarms found.")

    def check_cells_parameter_values(self, cell_ids, parameter, expected_values):
        if isinstance(expected_values, str):
            expected_values = [expected_values]
        for cell_id, expected_value in zip(cell_ids, expected_values):
            current_value = self.check_cell_parameter_value(cell_id, parameter)
            ta5g_admin_operations().assert_equal(expected=expected_value, actual=current_value)

    def wait_for_cells_parameters_value_change(self, cell_ids, parameter, expected_values, timeout=1100):
        ta5g_admin_operations().check_until_timeout(
            checking_func=self.check_cells_parameter_values,
            timeout=timeout,
            cell_ids=cell_ids,
            parameter=parameter,
            expected_values=expected_values,
        )

    @staticmethod
    def _get_cells_with_nrarfcn():
        """
        Get info from gNB about cells and their nrarfcn in dl and ul and return lists with information
        :param
        :return: nrarfcn_dl_list, nrarfcn_ul_list, cell_technology_list
        """
        nrarfcn_dl_list = []
        nrarfcn_ul_list = []
        cell_technology_list = []
        with ta_admin_interface.admin_interface() as admin_client:
            for cell in sorted(admin_client.get_cells_info(), key=lambda element: element['globalCellId']):
                cell_technology_list.append(cell['technology'])
                if cell_technology_list[-1] == "FDD":
                    nrarfcn_dl_list.append(cell['nrarfcnDl'])
                    nrarfcn_ul_list.append(cell['nrarfcnUl'])
                else:
                    nrarfcn_dl_list.append(cell['nrarfcn'])
                    nrarfcn_ul_list.append(cell['nrarfcn'])
        return nrarfcn_dl_list, nrarfcn_ul_list, cell_technology_list

    def verify_if_all_cells_have_same_blocking_state(self, expected_cells_blocking_state):
        """
        Verify if all cells have the same blocking state
        :param expected_cells_blocking_state:
        :return:
        """
        logger.console("Verify if all cells have the same blocking state: {}".format(expected_cells_blocking_state))
        cells_blocking_states = self.get_list_of_all_cells_blocking_states()
        for cell_blocking_status in cells_blocking_states:
            if cell_blocking_status != expected_cells_blocking_state:
                raise ExecutionFailed(
                    message='Cell blocking status: {} is not equal {}'.format(
                        cell_blocking_status, expected_cells_blocking_state
                    )
                )

    def lock_all_cells_classical(self):
        """
        Locking all cells from VM
        :return:
        """
        logger.info("Locking all cells", also_console=True)
        cells_ids = self.get_list_of_all_cells_ids()
        for cell_id in cells_ids:
            self.lock_single_cell_classical(cell_id=cell_id)

    def unlock_all_cells_classical(self):
        """
        Unlocking all cells from VM
        :return:
        """
        logger.info("Unlocking all cells", also_console=True)
        cells_ids = self.get_list_of_all_cells_ids()
        for cell_id in cells_ids:
            self.unlock_single_cell_classical(cell_id=cell_id)

    def lock_all_cells_aic(self, timeout=60):
        """
        Locking all cells from VM in vcu aic
        :param timeout: by default set to 60 seconds
        :return:
        """
        logger.info("Locking all cells", also_console=True)
        cells_ids = []
        number_of_cells = self.get_number_of_cells_aic()
        for cell in range(1, number_of_cells + 1):
            cells_ids.append(str(cell))
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            lock_cells_status = vcu_connection.lock_cells(cells_ids)
            while lock_cells_status['status'] != 'success' and timeout != 0:
                time.sleep(0.5)
                timeout -= 1
                lock_cells_status = vcu_connection.get_operation_state_of_locking_cells(operation_id=lock_cells_status['id'])
                if lock_cells_status['status'] == 'failure':
                    logger.console("It was not possible to lock all cells")
                    raise Exception
            if lock_cells_status['status'] == 'ongoing':
                logger.console("Locking cells still ongoing, timeout not enough")
                raise Exception
            if lock_cells_status['status'] == 'success':
                logger.console("Locking cells finished with success state")

