    def get_list_of_all_cells_ids(self):
        """
        :return: List of globalCellId
        """
        with ta_admin_interface.admin_interface() as admin_client:
            return [int(cell['globalCellId']) for cell in admin_client.get_cells_info()]

    def get_dict_of_cells_with_type(self):
        cells_ids = self.get_list_of_all_cells_ids()
        tdd_cells_ids = []
        fdd_cells_ids = []
        cells_dict = {}
        for i in cells_ids:
            if self.check_if_tdd_cell(global_cell_id=i):
                tdd_cells_ids.append(i)
            else:
                fdd_cells_ids.append(i)

        cells_dict['tdd'] = tdd_cells_ids
        cells_dict['fdd'] = fdd_cells_ids

        return cells_dict

    def get_list_of_all_cells_blocking_states(self):
        """
        :return: List of all cells blockingState
        """
        with ta_admin_interface.admin_interface() as admin_client:
            return [cell['status']['blockingState'] for cell in admin_client.get_cells_info()]

    def update_cell_parameters(self, enb, cell_id, optional_parameters=''):
        """
        Update changeable parameters in cell
        :param enb:
        :param cell_id:
        :param optional_parameters:
        :return:
        """
        logger.console(
            "Updating online changeable parameters {} for cell {}, enb {}".format(optional_parameters, cell_id, enb)
        )
        EgateInterface.send_egate_command(
            cmd='enb_cell_param enb={} id={} {}'.format(enb, cell_id, optional_parameters)
        )

    def link_lock(self, link_type, initiator_device, complementary_device):
        """
        Lock link to device
        E.g. Link Lock    link_type=x2    initiator_device=enb:4    complementary_device=enb:1
        :param link_type:
        :param initiator_device:
        :param complementary_device:
        :return:
        """
        logger.console(
            "Simulate error on {} link to {} initiated by {}".format(link_type, complementary_device, initiator_device)
        )
        EgateInterface.send_egate_command(
            cmd='link_lock link={} at={} to={}'.format(link_type, initiator_device, complementary_device)
        )

    def link_unlock(self, link_type, initiator_device, complementary_device):
        """
        Unlock link to device
        E.g. Link Unlock    link_type=x2    initiator_device=enb:4    complementary_device=enb:1
        :param link_type:
        :param initiator_device:
        :param complementary_device:
        :return:
        """
        logger.console("Unlock link {} to {} initiated by {}".format(link_type, complementary_device, initiator_device))
        EgateInterface.send_egate_command(
            cmd='link_unlock link={} at={} to={}'.format(link_type, initiator_device, complementary_device)
        )

