    def send_x2_configuration_update_with_cells_to_add(
        self, source_enb, target_enb, served_cells_to_add, new_anr_object_creation_delay='5s'
    ):
        """
        Send X2 Configuration Update
        :param source_enb:
        :param target_enb:
        :param served_cells_to_add:
        :param new_anr_object_creation_delay:
        :return:
        """
        logger.console("Sending X2 Configuration Update with cells {} to add".format(served_cells_to_add))
        self.update_cell_parameters(enb=source_enb, cell_id=served_cells_to_add, optional_parameters='status=enabled')
        self.send_configuration_update(
            source_enb=source_enb,
            optional_parameters='target={} served_cells_to_add={}'.format(target_enb, served_cells_to_add),
        )
        BuiltIn().sleep(new_anr_object_creation_delay)

    def send_x2_configuration_update_with_cells_to_delete(
        self, source_enb, target_enb, served_cells_to_delete, new_anr_object_creation_delay='5s'
    ):
        """
        :param source_enb:
        :param target_enb:
        :param served_cells_to_delete:
        :param new_anr_object_creation_delay:
        :return:
        """
        logger.console("Sending X2 Configuration Update with cells {} to delete".format(served_cells_to_delete))
        self.update_cell_parameters(
            enb=source_enb, cell_id=served_cells_to_delete, optional_parameters='status=disabled'
        )
        self.send_configuration_update(
            source_enb=source_enb,
            optional_parameters='target={} served_cells_to_delete={}'.format(target_enb, served_cells_to_delete),
        )
        BuiltIn().sleep(new_anr_object_creation_delay)

